<div x-data="{loading: false}"><form @submit.prevent="loading = true" class="space-y-5 rounded-xl border border-slate-200 bg-white p-6 shadow-sm"><div class="grid gap-5 sm:grid-cols-2"><div><x-input-label value="Asset code" /><x-text-input class="mt-1 block w-full" required /></div><div><x-input-label value="Asset name" /><x-text-input class="mt-1 block w-full" required /></div><div><x-input-label value="Category" /><select class="mt-1 block w-full rounded-lg border-slate-300"><option>Select category</option></select></div><div><x-input-label value="Condition" /><select class="mt-1 block w-full rounded-lg border-slate-300"><option>baik</option><option>rusak_ringan</option><option>rusak_berat</option></select></div></div><div class="rounded-lg border border-dashed border-slate-300 p-6 text-center text-sm text-slate-500">Asset image placeholder</div><button :disabled="loading" class="rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white"><span x-show="!loading">Save asset</span><span x-show="loading">Saving...</span></button></form></div>
